# We need to find the number of ways to make 25 cents using standard U.S. coins (pennies, nickels, dimes, quarters).
# The coins are defined as follows:
coin_values = [25, 10, 5, 1]  # quarters, dimes, nickels, pennies

ways = 0

# We'll iterate through the number of each coin possible
for q in range(10):  # 0 to 9 quarters (0 to 9 * 25 = 225 < 250)
    if 25 * q > 25:
        break
    for d in range(26):  # 0 to 25 dimes (0 to 25 * 10 = 250 < 250)
        if 10 * d > 25:
            break
    for n in range(51):  # 0 to 50 nickels (0 to 50 * 5 = 250 < 250)
