            break
        # Calculate the remaining cents after using q quarters, d dimes, n nickels, p pennies
        remaining_cents = 25 - (q * 25) - (d * 10) - (n * 5) - (p * 1)
        # If the remaining cents is 0, we have found a valid combination
        if remaining_cents == 0:
